-- 13A pack 01 ROLLBACK (REOPEN HOLES, UNSAFE): restore the captured ORIGINAL event_orders policies and table ACL exactly (includes the vulnerabilities)
-- 13A ORDERS HARDENING: PROPOSAL ONLY. NOT APPLIED ANYWHERE. GENERATED by db/proposed/13a-orders-hardening/build.mjs (node build.mjs --check fails if this file drifts from its inputs).
-- Apply gate: NO prod SQL without Joe's relayed yes + a Sentinel pass at the exact commit + a VERIFIED backup (single definition: db/proposed/13a-orders-hardening/RUNBOOK-APPLY-BACKUP-ROLLBACK.md section 2). Apply AFTER 12A (12A's drift guard expects the original event_orders ACL/policies). See README.md.
-- Run as postgres, ONE transaction, ON_ERROR_STOP (psql -v ON_ERROR_STOP=1) or a single-call SQL executor; right after BEGIN come SET LOCAL lock_timeout = '5s', the repo-wide pack advisory lock, and SET LOCAL lock_timeout = '5s' again.
-- UNSAFE: reopens forged-order insert, organizer rewrite and anon TRUNCATE. Requires the explicit acknowledgement below. Roll back 13A BEFORE rolling back 12A (12A's rollback guard expects the original orders ACL/policies).
BEGIN;
-- repo-wide pack key (same as R1 #136 / 12A): serialises every pack run; transaction-scoped; a second run waits for a running pack to commit or roll back, for at most 5 s:
-- lock_timeout is set BEFORE the lock (so the lock wait itself is bounded; a timeout set after a lock statement cannot bound that statement) and again right after it (every later lock wait). Expiry = SQLSTATE 55P03, nothing changed.
SET LOCAL lock_timeout = '5s';
SELECT pg_advisory_xact_lock(2979301232487107403);
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

-- EXPLICIT OVERRIDE REQUIRED. This pack REOPENS security holes ((1) orders_anon_insert: anon and any signed-in user can INSERT a forged paid order with a chosen qr_token; (2) event_orders_organizer_update: an organizer can UPDATE status / qr_token / checked_in_at / amount_cents of any order of their events; (3) table ACL ALL for anon + authenticated: anon can TRUNCATE event_orders (RLS does not apply to TRUNCATE) and DELETE / REFERENCES / TRIGGER / MAINTAIN). It refuses to run unless the same session has executed, BEFORE this file:
--     SET kil.rollback_reopen_ack = 'I-ACCEPT-REOPENING-HOLES-13A-01';
-- (psql: -c "SET kil.rollback_reopen_ack = '...'" -f <this file>, same invocation = same session; single-call executors: put that statement in front of this text in the same call).
DO $ack$
BEGIN
  IF coalesce(current_setting('kil.rollback_reopen_ack', true), '') IS DISTINCT FROM 'I-ACCEPT-REOPENING-HOLES-13A-01' THEN
    RAISE EXCEPTION '13A ROLLBACK-13A-01 (REOPEN HOLES, UNSAFE): refused. The acknowledgement is missing or wrong. This pack reopens: (1) orders_anon_insert: anon and any signed-in user can INSERT a forged paid order with a chosen qr_token; (2) event_orders_organizer_update: an organizer can UPDATE status / qr_token / checked_in_at / amount_cents of any order of their events; (3) table ACL ALL for anon + authenticated: anon can TRUNCATE event_orders (RLS does not apply to TRUNCATE) and DELETE / REFERENCES / TRIGGER / MAINTAIN. Nothing was changed. The default rollback pack keeps every hole closed; read the RUNBOOK before overriding.';
  END IF;
  RAISE WARNING '*** UNSAFE ROLLBACK 13A-01: REOPENING SECURITY HOLES ON PURPOSE ((1) orders_anon_insert: anon and any signed-in user can INSERT a forged paid order with a chosen qr_token; (2) event_orders_organizer_update: an organizer can UPDATE status / qr_token / checked_in_at / amount_cents of any order of their events; (3) table ACL ALL for anon + authenticated: anon can TRUNCATE event_orders (RLS does not apply to TRUNCATE) and DELETE / REFERENCES / TRIGGER / MAINTAIN). Acknowledged via kil.rollback_reopen_ack. Re-apply the APPLY pack as soon as the reason for this back-out is fixed. ***';
END
$ack$;

