-- restore the captured original: the two policies (same predicates), then the table-level ALL grants for anon + authenticated.
CREATE POLICY orders_anon_insert ON public.event_orders AS PERMISSIVE FOR INSERT TO anon, authenticated WITH CHECK (true);
CREATE POLICY event_orders_organizer_update ON public.event_orders AS PERMISSIVE FOR UPDATE TO authenticated
  USING (event_id IN (SELECT events.id FROM public.events WHERE events.owner_handle = public.my_handle()))
  WITH CHECK (event_id IN (SELECT events.id FROM public.events WHERE events.owner_handle = public.my_handle()));
REVOKE ALL ON TABLE public.event_orders FROM PUBLIC, anon, authenticated;
GRANT ALL ON TABLE public.event_orders TO anon, authenticated;

DO $post$
DECLARE bad text;
BEGIN
  SELECT string_agg(name || ' (expected ' || expected || ', got ' || actual || ')', ' ; ') INTO bad FROM (
WITH a(name, actual) AS (
  SELECT 'orders.relkind_rls' AS name, coalesce((SELECT c.relkind::text||'/'||c.relrowsecurity::text||'/'||c.relforcerowsecurity::text FROM pg_class c WHERE c.oid = 'public.event_orders'::regclass), 'ABSENT') AS actual
  UNION ALL SELECT 'orders.owner' AS name, coalesce((SELECT pg_get_userbyid(c.relowner)::text FROM pg_class c WHERE c.oid = 'public.event_orders'::regclass), 'ABSENT') AS actual
  UNION ALL SELECT 'orders.columns_md5' AS name, coalesce((SELECT md5(string_agg(a.attname::text||':'||format_type(a.atttypid,a.atttypmod), ',' ORDER BY a.attname::text COLLATE "C")) FROM pg_attribute a WHERE a.attrelid = 'public.event_orders'::regclass AND a.attnum > 0 AND NOT a.attisdropped), 'ABSENT') AS actual
  UNION ALL SELECT 'orders.indexes' AS name, coalesce((SELECT string_agg(i.indexname::text, ',' ORDER BY i.indexname::text COLLATE "C") FROM pg_indexes i WHERE i.schemaname = 'public' AND i.tablename = 'event_orders'), 'ABSENT') AS actual
